actions.script:
const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
cardList = []; needsReplyList = []; followUpList = []; meetingList = []; mailboxList = []; roomList = []
hasMailAccount = false; problemAccountList = []; failedParts = []
const nowMillis = toMillis(ec.user.nowTimestamp)
const day = (millis) => ec.l10n.format(new Date(Number(millis)), 'yyyy-MM-dd')
const todayText = day(nowMillis)
const INBOX = '/qapps/Comms/Inbox'
const count = (n) => ec.l10n.format(n, '#,##0')
// one part: its own errors and transaction; a failure leaves it out
const part = (name, run) => {
    ec.message.pushErrors()
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        failedParts.push(name)
        ec.logger.error(`Comms Home of user ${ec.user.userId}: ${name} failed and is left out: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const callService = (name, parameters) => {
    const out = ec.service.sync().name(name).parameters(parameters || {}).requireNewTransaction(true).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    if (out == null) throw new Error(`${name} answered nothing`)
    return out
}
const threads = (parameters) => Array.from(callService('mantle.party.CommunicationServices.find#InboxThreads', parameters).threadList || [])
const whenText = (millis) => {
    if (millis == null) return ''
    return day(millis) === todayText ? ec.l10n.format(new Date(Number(millis)), 'h:mm a') : ec.l10n.format(new Date(Number(millis)), 'MMM d')
}

// the unread of each account, the internal messages and the mailboxes
let mailboxes = []
part('unread', () => {
    const counts = callService('mantle.party.CommunicationServices.get#InboxUnreadCounts')
    let notSent = 0
    for (const account of Array.from(counts.accountList || [])) {
        if (account.isInternal) {
            cardList.push({key: 'internal', title: L('Messages'), value: count(account.unreadCount || 0), icon: 'sym_o_forum', link: INBOX + '?view=internal'})
            continue
        }
        hasMailAccount = true
        notSent += account.outboxErrorCount || 0
        if (['EasAuthFailed', 'EasError'].includes(account.statusId)) problemAccountList.push({emailAccountId: account.emailAccountId,
            accountName: account.accountName || account.emailAddress, problemText: account.statusId === 'EasAuthFailed' ? L('the sign-in failed') : L('the last sync failed'),
            canManage: account.canManage === true,
            link: '/qapps/Comms/Settings/MailAccounts/Account?emailAccountId=' + encodeURIComponent(account.emailAccountId) + (account.statusId === 'EasAuthFailed' ? '&fix=Y' : '')})
        cardList.push({key: 'account_' + account.emailAccountId, title: account.accountName || account.emailAddress || L('Mail'),
            value: account.unreadCount == null ? '–' : count(account.unreadCount), icon: 'sym_o_mail', link: INBOX + '?account=' + encodeURIComponent(account.emailAccountId)})
    }
    if (hasMailAccount) cardList.push({key: 'notSent', title: L('Not sent'), value: count(notSent), icon: notSent ? 'sym_o_error' : 'sym_o_outbox', link: INBOX + '?view=outbox'})
    mailboxes = Array.from(counts.mailboxList || [])
})
part('flagged', () => {
    const rows = threads({view: 'flagged', pageSize: 100})
    cardList.push({key: 'flagged', title: L('Flagged'), value: rows.length >= 100 ? '100+' : count(rows.length), icon: 'sym_o_flag', link: INBOX + '?view=flagged'})
})
part('snoozed', () => {
    const rows = threads({view: 'snoozed', pageSize: 200}).filter((row) => row.snoozedThruDate != null && day(toMillis(row.snoozedThruDate)) <= todayText)
    cardList.push({key: 'snoozed', title: L('Snoozed'), value: count(rows.length), icon: 'sym_o_snooze', link: INBOX + '?view=snoozed'})
})
// mentions: chat mentions and the unread notes to the user on records (Comments)
let rooms = null
part('rooms', () => { rooms = callService('org.moqui.impl.ChatServices.find#Rooms', {filter: 'unread', limit: 50}) })
part('mentions', () => {
    const comments = threads({store: 'internal', view: 'comments', unreadOnly: true, pageSize: 100}).length
    const total = comments + (rooms?.mentionTotal || 0)
    cardList.push({key: 'mentions', title: L('Mentions'), value: count(total), icon: 'sym_o_alternate_email',
        link: comments || !rooms?.mentionTotal ? INBOX + '?view=comments' : '/qapps/Comms/Chat'})
})
// missed calls not seen yet (the framework's call history), into the Calls history's Missed tab
part('missedCalls', () => {
    const missed = callService('org.moqui.impl.CallServices.count#MissedCalls').missedCount || 0
    cardList.push({key: 'missedCalls', title: L('Missed calls'), value: count(missed), icon: missed ? 'sym_o_phone_missed' : 'sym_o_call',
        link: '/qapps/Comms/Calls/History?outcome=missed'})
})
part('needsReply', () => {
    for (const row of threads({view: 'inbox', needsReply: true, pageSize: 10})) {
        // an internal row names its sender among its participants
        const sender = row.fromName || row.fromAddress || (row.fromPartyId ? (Array.from(row.participantList || [])
            .find((person) => person.partyId === row.fromPartyId)?.name || '') : '')
        needsReplyList.push({rowKey: row.rowKey, subject: row.subject || L('(no subject)'), who: sender,
            snippet: row.snippet || '', whenText: whenText(toMillis(row.sortDate)), store: row.store,
            link: INBOX + '?thread=' + encodeURIComponent(row.rowKey)})
    }
})
part('followUps', () => { followUpList = Array.from(callService('ironstone.comms.CommsHomeServices.get#HomeFollowUps').followUpList || []) })
part('meetings', () => { meetingList = Array.from(callService('ironstone.comms.CommsHomeServices.get#HomeMeetings').meetingList || []) })
mailboxList = mailboxes.filter((box) => (box.unreadCount || 0) > 0).slice(0, 10).map((box) => ({contactListId: box.contactListId,
    name: box.contactListName || box.contactListId, unreadCount: box.unreadCount, link: INBOX + '?mailbox=' + encodeURIComponent(box.contactListId)}))
if (rooms) roomList = Array.from(rooms.roomList || []).filter((room) => (room.unreadCount || 0) > 0 || (room.mentionCount || 0) > 0).slice(0, 10)
    .map((room) => ({chatRoomId: room.chatRoomId, name: room.displayName || room.roomName || room.chatRoomId, unreadCount: room.unreadCount || 0,
        mentionCount: room.mentionCount || 0, snippet: room.lastMessage ? ((room.lastMessage.senderName ? room.lastMessage.senderName + ': ' : '') +
            (room.lastMessage.snippet || '')) : '', link: '/qapps/Comms/Chat?chatRoomId=' + encodeURIComponent(room.chatRoomId)}))

const L = (text) => ec.l10n.localize(text)
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
const todayText = fmt(Number(ec.user.nowTimestamp), 'yyyy-MM-dd')
const seen = new Set()
const items = []
for (const row of Array.from(followUpRows ?? [])) {
    if (seen.has(row.workEffortId)) continue
    seen.add(row.workEffortId)
    const due = row.estimatedCompletionDate != null ? Number(String(row.estimatedCompletionDate)) : (row.estimatedStartDate != null ? Number(String(row.estimatedStartDate)) : null)
    if (due == null) continue
    const dueDay = fmt(due, 'yyyy-MM-dd')
    items.push({workEffortId: row.workEffortId, title: row.workEffortName || row.workEffortId, due: due,
        kindLabel: row.purposeEnumId === 'WepPhoneCall' ? L('Call') : L('Email'), icon: row.purposeEnumId === 'WepPhoneCall' ? 'sym_o_call' : 'sym_o_mail',
        dueText: dueDay === todayText ? L('Today') : fmt(due, 'EEE MMM d'), overdue: dueDay < todayText,
        link: '/qapps/Commons/Tasks/TaskDetail?workEffortId=' + encodeURIComponent(row.workEffortId)})
}
items.sort((left, right) => left.due - right.due)
followUpList = items.slice(0, 10)

const L = (text) => ec.l10n.localize(text)
meetingList = []
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) return
const nowMillis = Number(ec.user.nowTimestamp)
const fromMillis = fromDate ? Math.max(Number(fromDate), nowMillis) : nowMillis
const thruMillis = thruDate ? Number(thruDate) : nowMillis + 3 * 86400000
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
const todayText = fmt(nowMillis, 'yyyy-MM-dd')
const out = ec.service.sync().name('mantle.work.EventServices.get#FullCalendarData').parameters({partyId: partyId, start: fmt(fromMillis, 'yyyy-MM-dd'),
    end: fmt(thruMillis, 'yyyy-MM-dd'), excludeCancelled: true, titleGString: '${workEffort.workEffortName || workEffort.workEffortId}'}).call()
if (ec.message.hasError()) return
const events = Array.from(out?.eventList || []).filter((event) => (event.endMillis == null || Number(event.endMillis) > fromMillis)
        && Number(event.startMillis || 0) <= thruMillis)
    .sort((left, right) => Number(left.startMillis || 0) - Number(right.startMillis || 0)).slice(0, Math.min(Math.max(Number(limit) || 10, 1), 50))
if (!events.length) return
const ids = Array.from(new Set(events.map((event) => event.workEffortId)))
const rows = {}
for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', ids)
        .selectField('workEffortId,infoUrl,location,description').list()) rows[row.workEffortId] = row
const urlIn = (text) => { const match = /https?:\/\/[^\s<>"')]+/i.exec(String(text || '')); return match ? match[0] : null }
for (const event of events) {
    const row = rows[event.workEffortId] || {}
    const joinUrl = row.infoUrl && /^https?:\/\//i.test(String(row.infoUrl)) ? String(row.infoUrl) : (urlIn(row.location) || urlIn(row.description))
    const start = Number(event.startMillis)
    const dayText = fmt(start, 'yyyy-MM-dd') === todayText ? L('Today') : fmt(start, 'EEE MMM d')
    const started = start <= nowMillis
    meetingList.push({workEffortId: event.workEffortId, title: event.title || event.workEffortId,
        whenText: event.allDay ? dayText + ' · ' + L('All day') : dayText + ' ' + fmt(start, 'h:mm a') + (event.endMillis ? ' – ' + fmt(Number(event.endMillis), 'h:mm a') : ''),
        joinUrl: joinUrl, isNow: started && !event.allDay, link: '/qapps/Commons/Calendar/EventDetail?workEffortId=' + encodeURIComponent(event.workEffortId)})
}
